PREFIX pv: <http://ld.company.org/prod-vocab/>
PREFIX prodi: <http://ld.company.org/prod-instances/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?result WHERE {
  ?employee a pv:Employee ;
              pv:name "Sabrina" ;
              pv:department "Marketing" ;
              pv:email ?result .
}

PREFIX pv: <http://ld.company.org/prod-vocab/>
PREFIX prodi: <http://ld.company.org/prod-instances/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?result WHERE {
  ?expert a pv:Employee ;
            pv:hasSkill prodi:NetworkExpertise ;
            pv:worksInDepartment prodi:MarketingDepartment .
  ?expert rdfs:label ?result .
}

PREFIX pv: <http://ld.company.org/prod-vocab/>
PREFIX prodi: <http://ld.company.org/prod-instances/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?result WHERE {
  ?department a pv:Department ;
              pv:hasEmployee ?employee .
  ?employee a pv:TransducerExpert .
  BIND(?department AS ?result)
}

PREFIX pv: <http://ld.company.org/prod-vocab/>
PREFIX prodi: <http://ld.company.org/prod-instances/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT (COUNT(DISTINCT ?supplier) AS ?result) WHERE {
  ?supplier a pv:Supplier ;
              pv:locatedIn "France" .
}

PREFIX pv: <http://ld.company.org/prod-vocab/>
PREFIX prodi: <http://ld.company.org/prod-instances/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?result WHERE {
  ?supplier a pv:Supplier ;
              pv:locatedIn "France" ;
              pv:supplies prodi:Compensator .
}

PREFIX pv: <http://ld.company.org/prod-vocab/>
PREFIX prodi: <http://ld.company.org/prod-instances/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

ASK {
  ?supplier a pv:Supplier ;
              pv:locatedIn "Toulouse" .
}

PREFIX pv: <http://ld.company.org/prod-vocab/>
PREFIX prodi: <http://ld.company.org/prod-instances/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT DISTINCT ?result WHERE {
  ?supplier a pv:Supplier ;
              pv:locatedIn "Toulouse" .
  BIND(?supplier AS ?result)
}

PREFIX pv: <http://ld.company.org/prod-vocab/>
PREFIX prodi: <http://ld.company.org/prod-instances/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT ?result WHERE {
  ?product a pv:Oscillator ;
             pv:hasPrice ?price .
  FILTER(?price = (SELECT MIN(?minPrice) WHERE { 
    ?p a pv:Oscillator ; 
         pv:hasPrice ?minPrice .
  }))
} LIMIT 1

PREFIX pv: <http://ld.company.org/prod-vocab/>
PREFIX prodi: <http://ld.company.org/prod-instances/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?result WHERE {
  ?service a pv:Service ;
             pv:hasPrice ?price .
} ORDER BY DESC(?price) LIMIT 1

PREFIX pv: <http://ld.company.org/prod-vocab/>
PREFIX prodi: <http://ld.company.org/prod-instances/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?result WHERE {
  ?coil a pv:Coil ;
        pv:hasWeight ?weight ;
        pv:hasBaseArea ?baseArea .
  FILTER(?baseArea <= (15 * 15))
} ORDER BY DESC(?weight) LIMIT 1

PREFIX pv: <http://ld.company.org/prod-vocab/>
PREFIX prodi: <http://ld.company.org/prod-instances/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?result WHERE {
  ?product a pv:Product ;
             pv:suppliedBy ?supplier ;
             pv:compatibleWith prodi:U990-LCD-Inductor .
  ?supplier pv:country "US" .
}

PREFIX pv: <http://ld.company.org/prod-vocab/>
PREFIX prodi: <http://ld.company.org/prod-instances/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?result WHERE {
  ?pontiometer a pv:Pontiometer ;
               pv:hasVolume ?volume .
} ORDER BY ASC(?volume) LIMIT 1

PREFIX pv: <http://ld.company.org/prod-vocab/>
PREFIX prodi: <http://ld.company.org/prod-instances/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?result WHERE {
  ?coil a pv:Coil ;
          pv:hasDensity ?density .
} ORDER BY DESC(?density) LIMIT 1

PREFIX pv: <http://ld.company.org/prod-vocab/>
PREFIX prodi: <http://ld.company.org/prod-instances/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT ?name ?email ?phone WHERE {
  ?person a pv:StaffMember ;
            pv:name ?name ;
            pv:email ?email ;
            pv:phone ?phone .
  FILTER NOT EXISTS { ?otherPerson pv:manages ?person . }
} ORDER BY ?name

PREFIX pv: <http://ld.company.org/prod-vocab/>
PREFIX prodi: <http://ld.company.org/prod-instances/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT ?result (COUNT(?employee) AS ?employees) WHERE {
  ?department a pv:Department ;
              rdfs:label ?result .
  ?employee pv:worksIn ?department .
} GROUP BY ?result HAVING (?employees > 5)

PREFIX pv: <http://ld.company.org/prod-vocab/>
PREFIX prodi: <http://ld.company.org/prod-instances/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?supplier (ROUND(AVG(?price) * 100) / 100 AS ?averagePrice) WHERE {
  ?product pv:soldBy ?supplier ;
           pv:hasPrice ?price .
  FILTER(xsd:datatype(?price) = xsd:float)
} GROUP BY ?supplier

PREFIX pv: <http://ld.company.org/prod-vocab/>
PREFIX prodi: <http://ld.company.org/prod-instances/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

ASK {
  ?department a pv:Department .
  FILTER NOT EXISTS { ?department pv:hasManager ?manager . }
}

PREFIX pv: <http://ld.company.org/prod-vocab/>
PREFIX prodi: <http://ld.company.org/prod-instances/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?supplierName ?addressDetails WHERE {
  ?supplier a pv:Supplier ;
              pv:name ?supplierName ;
              pv:hasAddress ?address .
  ?address rdfs:label ?addressDetails .
}

PREFIX pv: <http://ld.company.org/prod-vocab/>
PREFIX prodi: <http://ld.company.org/prod-instances/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?result ?width ?height ?depth WHERE {
  ?result a pv:HardwareItem ;
            pv:hasDimension [ pv:dimensionType "width" ; pv:value ?width ] ;
                        [ pv:dimensionType "height" ; pv:value ?height ] ;
                        [ pv:dimensionType "depth" ; pv:value ?depth ] .
  FILTER(?width > ?height && ?depth < 50)
}

PREFIX pv: <http://ld.company.org/prod-vocab/>
PREFIX prodi: <http://ld.company.org/prod-instances/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?id ?name WHERE {
  ?item a pv:HardwareItem ;
          pv:id ?id ;
          rdfs:label ?name .
  FILTER NOT EXISTS { ?item pv:hasProductManager ?manager . }
}

PREFIX pv: <http://ld.company.org/prod-vocab/>
PREFIX prodi: <http://ld.company.org/prod-instances/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?result ?name ?width WHERE {
  ?item a pv:HardwareItem ;
          pv:hasDimension [ pv:dimensionType "width" ; pv:value ?width ] ;
          pv:hasID ?result .
  ?item rdfs:label ?name .
}
ORDER BY DESC(?width)
LIMIT (SELECT CEIL(COUNT(*) * 0.1) AS ?limit WHERE {
  ?item a pv:HardwareItem ;
          pv:hasDimension [ pv:dimensionType "width" ] .
})

PREFIX pv: <http://ld.company.org/prod-vocab/>
PREFIX prodi: <http://ld.company.org/prod-instances/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?result (COUNT(?product) AS ?products) WHERE {
  ?product a pv:Product ;
             pv:managedBy ?department .
} GROUP BY ?department ORDER BY DESC(?products) LIMIT 1
